RELATED_INDEX = {p["slug"]: p for p in PRODUCTS}
VEHICLE_INDEX = {v["slug"]: v for v in VEHICLES}


def _norm(x):
    return " ".join(str(x or "").strip().lower().split())


def products_for_vehicle(v):
    wanted = set(v.get("products") or [])
    if wanted:
        found = [p for p in PRODUCTS if p["slug"] in wanted]
        if found:
            return found
    out = []
    for p in PRODUCTS:
        f = p.get("fitment") or {}
        if _norm(f.get("make")) == _norm(v.get("make")) and _norm(f.get("model")) == _norm(v.get("model")):
            out.append(p)
    return out


def vehicles_for_product(p):
    f = p.get("fitment") or {}
    return [v for v in VEHICLES
            if _norm(v.get("make")) == _norm(f.get("make")) and _norm(v.get("model")) == _norm(f.get("model"))]


def category_name(cid):
    for c in CATEGORIES:
        if c["id"] == cid:
            return c["name"]
    return cid
